package com.termux.app.workspace;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
@org.junit.runner.RunWith(org.robolectric.RobolectricTestRunner.class) @org.robolectric.annotation.Config(sdk=28,application=android.app.Application.class)
public class AgentIndicatorStateTest {
 @Test public void readinessIsNotModelConnectivity()throws Exception{JSONObject s=new JSONObject().put("connected",true);assertEquals(AgentIndicatorState.State.IDLE,AgentIndicatorState.from(s,false));s.put("busy",true);assertEquals(AgentIndicatorState.State.WORKING,AgentIndicatorState.from(s,false));s.put("modelConnection",new JSONObject().put("state","retrying").put("attempt",2));assertEquals(AgentIndicatorState.State.RECONNECTING,AgentIndicatorState.from(s,false));assertEquals(AgentIndicatorState.State.ERROR,AgentIndicatorState.from(s,true));}
 @Test public void questionPermissionFailureAndTwoChatsStayIndependent()throws Exception{JSONObject a=new JSONObject().put("busy",true).put("forms",new JSONArray().put(new JSONObject().put("id","q"))),b=new JSONObject().put("busy",true);assertEquals(AgentIndicatorState.State.WAITING,AgentIndicatorState.from(a,false));assertEquals(AgentIndicatorState.State.WORKING,AgentIndicatorState.from(b,false));a.remove("forms");a.put("permission",new JSONObject().put("id","p"));assertEquals(AgentIndicatorState.State.WAITING,AgentIndicatorState.from(a,false));a.remove("permission");a.put("modelConnection",new JSONObject().put("state","failed"));assertEquals(AgentIndicatorState.State.ERROR,AgentIndicatorState.from(a,false));assertFalse(AgentIndicatorState.label(AgentIndicatorState.State.WAITING,true).isEmpty());assertFalse(AgentIndicatorState.label(AgentIndicatorState.State.WAITING,false).isEmpty());}
}
